private void btnCalculateActionPerformed(java.awt.event.ActionEvent evt) {
    try {
        // Step 1: Read purchase amount
        double amount = Double.parseDouble(txtAmount.getText().trim());
        double discount = 0.0;

        // Step 2: Check Customer Category Radio Button
        if (rbPremium.isSelected()) {
            discount = amount * 0.15; // 15% discount
        } else if (rbRegular.isSelected()) {
            discount = amount * 0.05; // 5% discount
        }

        // Step 3: Check Club Membership Checkbox for extra ₹200
        double extraDiscount = 0.0;
        if (chkMember.isSelected()) {
            extraDiscount = 200.0;
        }

        // Step 4: Calculate Net Payable
        double netPayable = amount - discount - extraDiscount;
        if (netPayable < 0) {
            netPayable = 0;
        }

        // Step 5: Display in result text field
        txtNetPay.setText(String.format("₹ %.2f", netPayable));

    } catch (NumberFormatException ex) {
        javax.swing.JOptionPane.showMessageDialog(this, 
            "Please enter a valid numeric purchase amount!", 
            "Input Error", 
            javax.swing.JOptionPane.ERROR_MESSAGE);
    }
}
```

