public class LinearSearchDemo {
    public static void main(String[] args) {
        int[] numbers = {12, 45, 23, 89, 34, 67, 90, 51};
        int target = 67;
        int foundIndex = -1;

        // Linear search traversal
        for (int i = 0; i < numbers.length; i++) {
            if (numbers[i] == target) {
                foundIndex = i;
                break;
            }
        }

        // Output result
        if (foundIndex != -1) {
            System.out.println("Target Element " + target + " found!");
            System.out.println("0-based Index: " + foundIndex);
            System.out.println("1-based Position: " + (foundIndex + 1));
        } else {
            System.out.println("Element " + target + " Not Found in array.");
        }
    }
}
